SET NAMES utf8mb4;
CREATE TABLE item (
  id int primary key,
  color varchar(20) CONSTRAINT item_color_enum_check CHECK (`color` IN ('red','blue')),
  tricky varchar(40) CONSTRAINT item_tricky_enum_check CHECK (`tricky` IN ('it''s','a,b','a)b','(x','back\\slash','say "hi"','é日本','')),
  qty int CONSTRAINT item_qty_min_check CHECK (`qty` >= 0) CONSTRAINT item_qty_max_check CHECK (`qty` <= 99),
  slug varchar(16) CONSTRAINT item_slug_minlength_check CHECK (char_length(`slug`) >= 2) CONSTRAINT item_slug_maxlength_check CHECK (char_length(`slug`) <= 16),
  ratio double CONSTRAINT item_ratio_min_check CHECK (`ratio` >= 0.5)
);
